// === Tab: mySketch ===
//Informed by epibyte's conceptual approach here: https://openprocessing.org/sketch/2843695 
//(Coded from scratch.  I don't use his (nicer) lerpCircles function, but I should!)
//Note: Although it is fun, this is a _really_ inefficient way to construct these shapes.  If you just want this shape, consider using a curve function, for example, instead!


let mouseHistory;
let palette;
let config;

function setup() {
	createCanvas(windowWidth, windowHeight);
	config = {
		numIntermediates: 100, //100 is smooth, but more is slower
		useChain: true, //should the visualisation chain from one historic point to another?  or have them joining across the time-loop?
		isRecording: true, //when false, loops playback through time
		showRecordingModeIndicator: true,
		loopTimeInSec: 5
	};

	palette = createPalette();
	mouseHistory = [];
window.simulatedMouseX = width / 2;
window.simulatedMouseY = height / 2;
}

function draw() {
	background(palette.background)
	if (config.isRecording) {
		updateMouseHistory();
	}
	drawSystem();
	config.showRecordingModeIndicator && drawRecordingModeIndicator();
}

function drawSystem() {

	const numCreatures = 5;
	const playbackOffset = config.isRecording ? 0 : frameCount;
	for (let creatureIx = 0; creatureIx < numCreatures; creatureIx++) {
		const hist1Ix = playbackOffset + fractionalHistoryIndex(creatureIx / numCreatures);
		//second index into history depends on our mode.  chain takes the next one.  otherwise we take one on the other side of history "loop"
		const secondFraction = config.useChain ? (creatureIx + 1) / numCreatures : 0.5 + creatureIx / numCreatures;
		const hist2Ix = playbackOffset + fractionalHistoryIndex(secondFraction)
		const colour = palette.colours[creatureIx % palette.colours.length]
		drawJoinedCircles(fromHist(hist1Ix, 120), fromHist(hist2Ix, 120), colour)
	}
}
//record the current mouse pos into history, kicking out the oldest value to make room, if we are "full"
function updateMouseHistory() {
	mouseHistory.push(createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
	const maxSamples = 60 * config.loopTimeInSec; //n seconds at 60FPS
	if (mouseHistory.length > maxSamples) {
		mouseHistory.shift()
	}
}

//get an index for mouseHistory for the given fraction, wrapping if necessary
function fractionalHistoryIndex(frac) {
	if (frac >= 1) {
		frac -= 1;
	}
	return floor(mouseHistory.length * frac);
}

/** make a circle data from historic mouse position at given index, with given radius. wrapping if necessary */
function fromHist(historyIndex, radius) {
	return {
		pos: mouseHistory[historyIndex % mouseHistory.length],
		radius
	}
}

function drawJoinedCircles(c1, c2, fillColour) {
	push()
	fill(fillColour)
	noStroke()
	lerpCircles(c1, c2, 1 / config.numIntermediates);
	pop()

}

function lerpCircles(c1, c2, fracStep) {
	for (let frac = 0; frac <= 1; frac += fracStep) {
		const pos = p5.Vector.lerp(c1.pos, c2.pos, frac);
		//Our bridging radius should scoop rather than linearly interpolate between the two circle radii
		//it turns out we can use bezierPoint, with two scalars, to do this:
		const radius = bezierPoint(c1.radius, c1.radius / 5, c2.radius / 5, c2.radius, frac);
		circle(pos.x, pos.y, radius)
	}
}

function mousePressed() {
	background(100)
}

function createPalette() {
	const palettes = [
		// {
		// 	colours: [
		// 		"#aaff00",
		// 		"#ffaa00",
		// 		"#ff00aa",
		// 		"#aa00ff",
		// 		"#00aaff"
		// 	],
		// 	background: "#222"
		// },
		{
			colours: [
				"#5e9fa3",
				"#b05574",
				"#f87e7b",
				"#fab87f",
				"#dcd1b4",
			],
			background: "#222"
		}
	]
	return random(palettes)
}

function keyPressed() {
	if (key === " ") {
		config.useChain = !config.useChain;
	}
	if (key === "r") {
		config.isRecording = !config.isRecording;
	}
	if (key === "i") {
		config.showRecordingModeIndicator = !config.showRecordingModeIndicator;
	}
	if (key === "p") {
		palette = createPalette()
	}
}

function drawRecordingModeIndicator() {
	push()
	const alphaVal = 255; //map(sin(frameCount / 20), -1, 1, 0, 255);
	translate(width - 100, 100)
	noStroke()

	const recordingLoopFraction = (frameCount / (60 * config.loopTimeInSec)) % 1;

	const signDiameter = 60;
	if (config.isRecording) {
		const textColour = color("#dcd1b4");
		const circleColour = color("#f87e7b");
		textColour.setAlpha(alphaVal);
		circleColour.setAlpha(alphaVal);
		fill(circleColour)
		circle(0, 0, signDiameter)
		textAlign(CENTER, CENTER)
		fill(textColour)
		noStroke()
		textSize(30)
		text("R", 0, 0)

		//"clock hand"
		stroke(textColour)
		rotate(TWO_PI * recordingLoopFraction)
		strokeWeight(8)
		point(signDiameter * 0.6, 0)
	} else {
		const circleColour = color("#5e9fa3");
		circleColour.setAlpha(alphaVal)
		const triangleColour = color("#dcd1b4");
		triangleColour.setAlpha(alphaVal);
		fill(circleColour)
		circle(0, 0, signDiameter)

		//draw a triangle
		const angles = [0, 1, 2].map(count => count * TWO_PI / 3);
		fill(triangleColour)
		const corners = angles.map(angle => p5.Vector.fromAngle(angle, signDiameter * 0.3));
		beginShape()
		corners.forEach(c => vertex(c.x, c.y));
		endShape()
	}

	pop()
}
